type Tab = 'library' | 'recent' | 'me';
type Screen = 'main' | 'sources' | 'document' | 'seriesDetail' | 'about' | 'cache';
type ThemeContextValue = { mode: ThemeMode; isDark: boolean; setMode: (mode: ThemeMode) => void };
const ThemeContext = createContext<ThemeContextValue>({ mode: 'system', isDark: false, setMode: () => undefined });
function useTheme() { return useContext(ThemeContext); }
function compactAuthor(author: string) {
  const names = author.split(/[、,，;；/|]+/).map(name => name.trim()).filter(Boolean);
  if (!names.length) return '';
  const joined = names.join('、');
  return names.length > 1 && joined.length > 12 ? `${names[0]}等人` : joined;
}
let comicDarkTheme = true;
let comicRtlTheme = false;
function Slider(props: React.ComponentProps<typeof NativeSlider>) { return <NativeSlider {...props} inverted={comicRtlTheme} />; }

function IconButton({ name, onPress, dark = false, label, color }: { name: keyof typeof Ionicons.glyphMap; onPress?: () => void; dark?: boolean; label?: string; color?: string }) {
  const { isDark } = useTheme();
  return <Pressable accessibilityRole="button" accessibilityLabel={label ?? name} hitSlop={8} android_ripple={{ color: 'rgba(114,87,231,.18)', borderless: true }} onPress={onPress} style={({ pressed }) => [styles.iconButton, pressed && styles.pressed]}><Ionicons name={name} size={22} color={color ?? (dark || isDark ? '#F7F6FB' : '#28262D')} /></Pressable>;
}

function Progress({ value, color = '#7C5CFC' }: { value: number; color?: string }) {
  const { isDark } = useTheme();
  return <View style={[styles.progressTrack, { width: '100%', flex: 0 }, isDark && styles.progressTrackDark]}><View style={[styles.progressFill, { width: `${value * 100}%`, backgroundColor: color }]} /></View>;
}

function SeriesProgress({ series, inverse = false, compact = false }: { series: LibrarySeries; inverse?: boolean; compact?: boolean }) {
  if (compact) return <CompactSeriesProgress series={series} inverse={inverse} />;
  const chapterPosition = series.currentChapterNumber ? Math.min(1, Math.max(0, series.currentChapterNumber / Math.max(1, series.chapterCount))) : 0;
  const chapterText = series.currentChapterId ? `章节 ${series.currentChapterNumber || 1} / ${series.chapterCount}` : '章节 0 / ' + series.chapterCount;
  return <View style={styles.seriesProgress}><Text numberOfLines={1} style={[styles.progressCaption, inverse && styles.progressCaptionInverse]}>{chapterText}</Text><Progress value={chapterPosition} color="#0F9F91" /><Text style={[styles.progressCaption, inverse && styles.progressCaptionInverse]}>本章 {Math.round(series.progress * 100)}%</Text><Progress value={series.progress} color="#A855F7" /></View>;
}

function CompactProgress({ value, color }: { value: number; color: string }) {
  const { isDark } = useTheme();
  return <View style={[layoutStyles.compactProgressTrack, isDark && layoutStyles.compactProgressTrackDark]}><View style={[layoutStyles.compactProgressFill, { width: `${Math.max(0, Math.min(1, value)) * 100}%`, backgroundColor: color }]} /></View>;
}

function CompactSeriesProgress({ series, inverse }: { series: LibrarySeries; inverse?: boolean }) {
  const { isDark } = useTheme();
  const chapterPosition = series.currentChapterNumber ? Math.min(1, Math.max(0, series.currentChapterNumber / Math.max(1, series.chapterCount))) : 0;
  const caption = { color: inverse ? '#E7E0FF' : isDark ? '#D0C8DD' : '#77717D', fontSize: 10, lineHeight: 14, fontWeight: '700' as const };
  const chapterText = series.currentChapterId ? `章节 ${series.currentChapterNumber || 1} / ${series.chapterCount}` : `章节 0 / ${series.chapterCount}`;
  return <View style={layoutStyles.seriesProgressCompact}><Text numberOfLines={1} style={caption}>{chapterText}</Text><CompactProgress value={chapterPosition} color="#0F9F91" /><Text style={caption}>本章 {Math.round(series.progress * 100)}%</Text><CompactProgress value={series.progress} color="#A855F7" /></View>;
}

function SeriesLibrary({ series, importing, refreshLibraries, openSeries, continueSeries, openSources }: { series: LibrarySeries[]; importing: boolean; refreshLibraries: () => void; openSeries: (value: LibrarySeries) => void; continueSeries: (value: LibrarySeries) => void; openSources: () => void }) {
  const [query, setQuery] = useState('');
  const [searching, setSearching] = useState(false);
  const { isDark } = useTheme();
  const { width: viewportWidth } = useWindowDimensions();
  const visible = series.filter(item => `${item.title} ${item.author} ${item.chapterSearchText}`.toLowerCase().includes(query.trim().toLowerCase()));
  const featured = series.find(item => item.currentChapterId !== null);
  useEffect(() => { if (!searching) return; const subscription = BackHandler.addEventListener('hardwareBackPress', () => { setSearching(false); setQuery(''); return true; }); return () => subscription.remove(); }, [searching]);
  const header = <View><View style={styles.header}><Text style={[styles.title, isDark && styles.textPrimaryDark]}>我的书架</Text><IconButton name={searching ? 'close' : 'search'} label={searching ? '关闭搜索' : '搜索作品'} onPress={() => { setSearching(value => !value); if (searching) setQuery(''); }} /></View>{searching && <View style={[styles.search, isDark && uiStyles.searchDark]}><Ionicons name="search" size={18} color={isDark ? '#C4BBCF' : '#8A8691'} /><TextInput value={query} onChangeText={setQuery} autoFocus placeholder="搜索作品名或作者" placeholderTextColor={isDark ? '#B8B1C2' : '#8A8691'} style={[styles.searchInput, isDark && uiStyles.searchInputDark]} /></View>}{!searching && featured && <Pressable accessibilityRole="button" style={[styles.continueCard, layoutStyles.continueCardCompact]} onPress={() => continueSeries(featured)}>{featured.coverUri ? <Image source={{ uri: featured.coverUri }} style={[styles.continueCover, layoutStyles.continueCoverCompact]} /> : <View style={[styles.continueFormat, layoutStyles.continueCoverCompact]}><Text style={styles.formatText}>漫画</Text></View>}<View style={[styles.continueBody, layoutStyles.continueBodyCompact]}><View style={layoutStyles.continueTopRow}><Text numberOfLines={1} style={[styles.continueTitle, layoutStyles.continueTitleTop]}>{featured.title}</Text><View style={[styles.pill, layoutStyles.pillRight]}><Text style={styles.pillText}>继续阅读</Text></View></View><View style={layoutStyles.continueAuthorSlot}>{featured.author && <Text numberOfLines={1} style={layoutStyles.continueAuthor}>{compactAuthor(featured.author)}</Text>}</View><SeriesProgress series={featured} inverse compact /></View></Pressable>}<View style={styles.sectionHeader}>{searching ? <View><Text numberOfLines={1} style={[styles.sectionTitle, isDark && styles.textPrimaryDark]}>{query.trim() ? `搜索“${query.trim()}”` : '搜索作品'}</Text><Text style={[styles.meta, isDark && styles.textMutedDark]}>{visible.length} 部</Text></View> : <><Text style={[styles.sectionTitle, isDark && styles.textPrimaryDark]}>全部作品 · {series.length}</Text><View style={layoutStyles.libraryHeaderActions}><Pressable accessibilityRole="button" accessibilityLabel="刷新漫画源" onPress={refreshLibraries} style={({ pressed }) => [styles.folderButton, isDark && uiStyles.folderButtonDark, pressed && styles.pressed]}><Ionicons name={importing ? 'sync' : 'refresh'} size={18} color={isDark ? '#B9A5FF' : '#7257E7'} /></Pressable><Pressable accessibilityRole="button" accessibilityLabel="打开漫画源设置" onPress={openSources} style={({ pressed }) => [styles.folderButton, isDark && uiStyles.folderButtonDark, pressed && styles.pressed]}><Ionicons name="folder-open" size={18} color={isDark ? '#B9A5FF' : '#7257E7'} /></Pressable></View></>}</View></View>;
  const empty = series.length === 0 ? <View style={[styles.emptyLibrary, isDark && styles.cardDark]}><View style={styles.emptyLibraryIcon}><Ionicons name="library-outline" size={38} color="#7257E7" /></View><Text style={[styles.emptyTitle, isDark && styles.textPrimaryDark]}>尚未设置漫画库</Text><Text style={[styles.emptyDescription, isDark && styles.textMutedDark]}>选择一个漫画源；其中每个一级子文件夹会作为一本作品，文件夹内的 EPUB、MOBI、PDF 会按章节整理。</Text><Pressable accessibilityRole="button" onPress={openSources} style={styles.primaryButton}><Text style={styles.primaryText}>添加漫画源</Text></Pressable></View> : <View style={styles.empty}><Text style={[styles.meta, isDark && styles.textMutedDark]}>没有匹配的作品</Text></View>;
  return <FlatList data={visible} numColumns={2} keyExtractor={item => String(item.id)} contentInsetAdjustmentBehavior="automatic" showsVerticalScrollIndicator={false} contentContainerStyle={[styles.page, isDark && styles.pageDark]} columnWrapperStyle={{ gap: 16 }} ListHeaderComponent={header} ListEmptyComponent={empty} renderItem={({ item }) => <Pressable accessibilityRole="button" onPress={() => openSeries(item)} style={[styles.book, { width: Math.max(0, (viewportWidth - 48 - 16) / 2) }]}>{item.coverUri ? <Image source={{ uri: item.coverUri }} style={styles.cover} /> : <View style={[styles.cover, layoutStyles.formatPlaceholder]}><Ionicons name="book" size={34} color="#fff" /><Text style={styles.formatText}>漫画</Text></View>}<Text numberOfLines={2} style={[styles.bookTitle, layoutStyles.bookTitleTight, isDark && styles.textPrimaryDark]}>{item.title}</Text><View style={layoutStyles.bookAuthorSlot}>{item.author && <Text numberOfLines={1} style={[styles.bookMeta, layoutStyles.bookMetaTight, isDark && styles.textMutedDark]}>{compactAuthor(item.author)}</Text>}</View><SeriesProgress series={item} compact /></Pressable>} />;
}

