function SeriesDetail({ series, chapters: seriesChapters, back, openChapter, continueReading, uploadCover }: { series: LibrarySeries; chapters: StoredChapter[]; back: () => void; openChapter: (chapter: StoredChapter) => void; continueReading: () => void; uploadCover: () => void }) {
  const chapterIndex = series.currentChapterId === null ? -1 : Math.max(0, seriesChapters.findIndex(item => item.id === series.currentChapterId));
  const chapterProgress = series.currentChapterId === null ? 0 : (chapterIndex + 1) / Math.max(1, seriesChapters.length);
  const { isDark } = useTheme();
  const hasHistory = series.currentChapterId !== null;
  const header = <View><View style={[styles.detailTop, layoutStyles.detailTopAligned]}><IconButton name="chevron-back" label="返回作品" onPress={back} /><IconButton name="image-outline" label="更换封面" onPress={uploadCover} /></View><View style={styles.hero}>{series.coverUri ? <Image source={{ uri: series.coverUri }} style={styles.detailCover} /> : <View style={[styles.detailCover, layoutStyles.formatPlaceholder]}><Ionicons name="book" size={38} color="#fff" /></View>}<View style={styles.heroBody}><Text style={[styles.detailTitle, isDark && styles.textPrimaryDark]}>{series.title}</Text><View style={layoutStyles.detailAuthorSlot}>{series.author && <Text numberOfLines={1} style={[{ color: '#88838E', fontSize: 12, marginTop: -2, marginBottom: 5 }, isDark && styles.textMutedDark]}>{compactAuthor(series.author)}</Text>}</View><Text style={[styles.heroProgress, isDark && styles.textMutedDark]}>章节进度 {chapterIndex + 1} / {seriesChapters.length}</Text><Progress value={chapterProgress} color="#0F9F91" /><Text style={[styles.heroProgress, isDark && styles.textMutedDark]}>当前章节 {Math.round(series.progress * 100)}%</Text><Progress value={series.progress} color="#A855F7" /></View></View><Pressable accessibilityRole="button" accessibilityLabel={hasHistory ? '继续阅读' : '开始阅读'} style={({ pressed }) => [styles.primaryButton, pressed && styles.pressed]} onPress={continueReading}><Ionicons name="book" size={20} color="#fff" /><Text style={styles.primaryText}>{hasHistory ? '继续阅读' : '开始阅读'}</Text></Pressable><View style={styles.sectionHeader}><Text style={[styles.sectionTitle, isDark && styles.textPrimaryDark]}>目录</Text><Text style={[styles.meta, isDark && styles.textMutedDark]}>共 {seriesChapters.length} 章</Text></View></View>;
  return <SafeAreaView style={[styles.safe, isDark && styles.safeDark]}><FlatList data={seriesChapters} keyExtractor={chapter => String(chapter.id)} contentInsetAdjustmentBehavior="automatic" contentContainerStyle={[styles.detailPage, isDark && styles.pageDark]} ListHeaderComponent={header} ListEmptyComponent={<View style={styles.empty}><Text style={[styles.meta, isDark && styles.textMutedDark]}>尚未找到章节</Text></View>} renderItem={({ item: chapter }) => <Pressable accessibilityRole="button" accessibilityLabel={`打开${chapter.chapterTitle}`} style={({ pressed }) => [styles.chapter, isDark && styles.chapterDark, pressed && styles.pressed]} onPress={() => openChapter(chapter)}><View style={[styles.chapterNumber, isDark && uiStyles.chapterNumberDark]}><Text style={[styles.chapterNumberText, isDark && uiStyles.chapterNumberTextDark]}>{chapter.chapterNumber}</Text></View><View style={styles.flex}><Text numberOfLines={1} style={[styles.rowTitle, isDark && styles.textPrimaryDark]}>{chapter.chapterTitle}</Text><Text style={[styles.meta, isDark && styles.textMutedDark]}>{chapter.format.toUpperCase()} · {Math.round(chapter.progress * 100)}%</Text></View>{chapter.id === series.currentChapterId && <View style={styles.dot} />}</Pressable>} /></SafeAreaView>;
}

