function Recent({ series, openSeries, clearHistory }: { series: LibrarySeries[]; openSeries: (value: LibrarySeries) => void; clearHistory: (id: number) => void }) {
  const readSeries = series.filter(item => item.currentChapterId !== null);
  const now = Date.now(); const day = 24 * 60 * 60 * 1000;
  const sections: { title: string; data: LibrarySeries[] }[] = [
    { title: '今天', data: readSeries.filter(item => now - item.updatedAt < day) },
    { title: '一周内', data: readSeries.filter(item => { const age = now - item.updatedAt; return age >= day && age < 7 * day; }) },
    { title: '更早', data: readSeries.filter(item => now - item.updatedAt >= 7 * day) },
  ].filter(section => section.data.length > 0);
  const { isDark } = useTheme();
  return <SectionList sections={sections} keyExtractor={item => String(item.id)} contentInsetAdjustmentBehavior="automatic" contentContainerStyle={[styles.page, isDark && styles.pageDark]} renderSectionHeader={({ section }) => <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10, marginTop: 18, marginBottom: 10 }}><Text style={{ color: isDark ? '#B8B1C2' : '#8A8691', fontSize: 12, fontWeight: '700' }}>{section.title}</Text><View style={{ flex: 1, height: 1, backgroundColor: isDark ? '#342E3B' : '#E4E1E7' }} /></View>} renderItem={({ item }) => <View style={styles.historyRow}>{item.coverUri ? <Image source={{ uri: item.coverUri }} style={styles.historyCover} /> : <View style={styles.historyFormat}><Text style={styles.formatText}>漫画</Text></View>}<Pressable accessibilityRole="button" style={styles.flex} onPress={() => openSeries(item)}><Text numberOfLines={1} ellipsizeMode="tail" style={[styles.rowTitle, isDark && styles.textPrimaryDark]}>{item.title}</Text><View style={layoutStyles.historyAuthorSlot}>{item.author && <Text numberOfLines={1} style={[{ color: '#88838E', fontSize: 12, marginBottom: 3 }, isDark && styles.textMutedDark]}>{compactAuthor(item.author)}</Text>}</View><Text numberOfLines={1} style={[styles.meta, isDark && styles.textMutedDark]}>阅读至 {item.currentChapterTitle || '章节'} · {Math.round(item.progress * 100)}%</Text></Pressable><Pressable accessibilityRole="button" accessibilityLabel={`删除 ${item.title} 的阅读记录`} onPress={() => clearHistory(item.id)} style={styles.historyDelete} hitSlop={8}><Ionicons name="trash-outline" size={20} color={isDark ? '#B8B1C2' : '#9A949F'} /></Pressable></View>} ListHeaderComponent={<Text style={[styles.title, { marginBottom: 8 }, isDark && styles.textPrimaryDark]}>最近阅读</Text>} ListEmptyComponent={<View style={styles.empty}><Ionicons name="time-outline" size={36} color="#B2ADB7" /><Text style={[styles.meta, isDark && styles.textMutedDark]}>开始阅读一个章节后，它会出现在这里</Text></View>} />;
}
