function Me({ navigate }: { navigate: (screen: Screen) => void }) {
  const groups: [keyof typeof Ionicons.glyphMap, string][][] = [[['folder-open-outline', '漫画源'], ['cube-outline', '缓存']], [['information-circle-outline', '关于 Veader']]];
  const destinations: Record<string, Screen> = { '漫画源': 'sources', '缓存': 'cache', '关于 Veader': 'about' };
  const { mode, isDark, setMode } = useTheme();
  const modeLabel = mode === 'system' ? '自动' : mode === 'dark' ? '黑夜' : '白天';
  const cycleTheme = () => {
    const nextMode: ThemeMode = mode === 'system' ? 'light' : mode === 'light' ? 'dark' : 'system';
    const label = nextMode === 'system' ? '自动' : nextMode === 'dark' ? '黑夜' : '白天';
    setMode(nextMode);
    if (Platform.OS === 'android') ToastAndroid.show(`已切换到${label}模式`, ToastAndroid.SHORT);
    else Alert.alert('界面主题', `已切换到${label}模式`);
  };
  return <View style={[styles.flex, isDark && styles.pageDark]}><ScrollView contentInsetAdjustmentBehavior="automatic" contentContainerStyle={[styles.page, isDark && styles.pageDark]}><View style={styles.header}><Text style={[styles.title, isDark && styles.textPrimaryDark]}>我的</Text><Pressable accessibilityRole="button" accessibilityLabel={`切换界面主题，当前${modeLabel}`} style={[styles.themeButton, isDark && styles.themeButtonDark]} onPress={cycleTheme}><Ionicons name={mode === 'dark' ? 'moon' : mode === 'system' ? 'contrast' : 'sunny'} size={20} color={isDark ? '#5B21B6' : '#7257E7'} /></Pressable></View>{groups.map((group, groupIndex) => <View style={[styles.settingsGroup, isDark && styles.cardDark]} key={groupIndex}>{group.map(([icon, label], index) => <Pressable accessibilityRole="button" key={label} onPress={() => navigate(destinations[label]!)} style={({ pressed }) => [styles.settingRow, index < group.length - 1 && styles.divider, isDark && styles.dividerDark, pressed && styles.pressed]}><View style={styles.settingIcon}><Ionicons name={icon} size={20} color="#7257E7" /></View><Text style={[styles.settingLabel, isDark && styles.textPrimaryDark]}>{label}</Text><Ionicons name="chevron-forward" size={18} color={isDark ? '#B8B1C2' : '#AAA5B0'} /></Pressable>)}</View>)}</ScrollView></View>;
}

